import time

BG = "#F3F5F2"
NAVY = "#172B4D"
GREEN = "#0B806B"
PALE = "#E2F3ED"
WHITE = "#FFFFFF"
TEXT = "#243247"
MUTED = "#718096"
ORANGE = "#F0A33A"

SUBJECTS = {v['subject']: v['questions'] for v in QUESTIONS_DATA.values()}
SUBJECT_ORDER = ["Use of English", "Mathematics", "Physics", "Chemistry"]
# Match subject names even if the question bank's keys are in a different order.
SUBJECTS = {name: next(v['questions'] for v in QUESTIONS_DATA.values() if v['subject'] == name) for name in SUBJECT_ORDER}

class JambApp:
    def __init__(self, root):
        self.root = root
        self.root.title("JAMB CBT Studio | Practice & Exam")
        self.root.geometry("1100x760")
        self.root.minsize(850, 620)
        self.root.configure(bg=BG)
        self.mode = "exam"
        self.subject = None
        self.questions = []
        self.answers = {}
        self.flagged = set()
        self.idx = 0
        self.remaining = 3600
        self.timer_job = None
        # Keyboard controls work even when the mouse is not used.
        self.root.bind_all("<KeyPress>", self.handle_keypress)
        self.show_home()

    def handle_keypress(self, event):
        """Keyboard shortcuts for CBT navigation and answering."""
        if not self.questions or not hasattr(self, "option_buttons"):
            return
        key = (event.keysym or "").lower()
        char = (event.char or "").lower()
        # Ignore shortcuts on screens other than the active question screen.
        if not hasattr(self, "palette_buttons") or not self.palette_buttons:
            return
        if key in ("a", "b", "c", "d", "e") or char in ("a", "b", "c", "d", "e"):
            answer = key if key in ("a", "b", "c", "d", "e") else char
            answer = answer.upper()
            if answer in self.questions[self.idx].get("options", {}):
                self.select(answer)
            return "break"
        if key == "left":
            self.previous(); return "break"
        if key == "return" and (event.state & 0x4):
            self.submit(); return "break"
        if key == "right" or key == "return":
            self.next_question(); return "break"
        if key == "f":
            self.toggle_flag(); return "break"
        if key in ("1", "2", "3", "4", "5", "6", "7", "8", "9"):
            target = int(key) - 1
            if target < len(self.questions):
                self.jump(target)
            return "break"
        if key == "home":
            self.jump(0); return "break"
        if key == "end":
            self.jump(len(self.questions) - 1); return "break"
        if key == "escape":
            self.show_home(); return "break"

    def clear(self):
        if self.timer_job:
            self.root.after_cancel(self.timer_job)
            self.timer_job = None
        for w in self.root.winfo_children(): w.destroy()

    def button(self, parent, text, command, bg=GREEN, fg=WHITE, width=None):
        return tk.Button(parent, text=text, command=command, bg=bg, fg=fg,
                         activebackground=bg, activeforeground=fg, relief="flat",
                         bd=0, padx=16, pady=10, font=("Segoe UI", 10, "bold"),
                         cursor="hand2", width=width)

    def header(self, title, subtitle="Your personal computer-based test practice room"):
        bar = tk.Frame(self.root, bg=NAVY, height=86)
        bar.pack(fill="x")
        bar.pack_propagate(False)
        tk.Label(bar, text="J•", bg=NAVY, fg="#6EE7C5", font=("Segoe UI", 25, "bold")).pack(side="left", padx=(24, 12))
        block = tk.Frame(bar, bg=NAVY); block.pack(side="left", pady=14)
        tk.Label(block, text=title, bg=NAVY, fg=WHITE, font=("Segoe UI", 19, "bold")).pack(anchor="w")
        tk.Label(block, text=subtitle, bg=NAVY, fg="#C8D5E5", font=("Segoe UI", 9)).pack(anchor="w", pady=(2,0))

    def show_home(self):
        self.clear()
        self.header("JAMB CBT STUDIO", "A cleaner way to practise, prepare, and track your progress")
        wrap = tk.Frame(self.root, bg=BG); wrap.pack(fill="both", expand=True, padx=34, pady=28)
        hero = tk.Frame(wrap, bg=PALE, padx=28, pady=24); hero.pack(fill="x")
        tk.Label(hero, text="READY WHEN YOU ARE.", bg=PALE, fg=GREEN, font=("Segoe UI", 10, "bold")).pack(anchor="w")
        tk.Label(hero, text="Build confidence one question at a time.", bg=PALE, fg=NAVY,
                 font=("Segoe UI", 23, "bold")).pack(anchor="w", pady=(7,4))
        tk.Label(hero, text="240 questions • 4 subjects • Timed exam and learning modes", bg=PALE,
                 fg=TEXT, font=("Segoe UI", 11)).pack(anchor="w")
        tk.Label(wrap, text="CHOOSE YOUR MODE", bg=BG, fg=MUTED, font=("Segoe UI", 9, "bold")).pack(anchor="w", pady=(24,10))
        modes = tk.Frame(wrap, bg=BG); modes.pack(fill="x")
        self.mode_card(modes, "Timed examination", "60 questions · 60 minutes", "Start a mock CBT with a countdown and final score.", "exam", 0)
        self.mode_card(modes, "Practice & learn", "No countdown", "Check answers and explanations as you work.", "practice", 1)
        tk.Label(wrap, text="SUBJECTS INCLUDED", bg=BG, fg=MUTED, font=("Segoe UI", 9, "bold")).pack(anchor="w", pady=(24,10))
        grid = tk.Frame(wrap, bg=BG); grid.pack(fill="x")
        details = [("01", "Use of English", "Language & comprehension"), ("02", "Mathematics", "Numbers & problem solving"), ("03", "Physics", "Concepts & calculations"), ("04", "Chemistry", "Matter & reactions")]
        for i,(num,name,desc) in enumerate(details):
            card=tk.Frame(grid,bg=WHITE,highlightbackground="#DDE4E0",highlightthickness=1,padx=16,pady=14)
            card.grid(row=i//2,column=i%2,sticky="ew",padx=(0 if i%2==0 else 8,8 if i%2==0 else 0),pady=5)
            tk.Label(card,text=num,bg=WHITE,fg=GREEN,font=("Segoe UI",10,"bold")).pack(anchor="w")
            tk.Label(card,text=name,bg=WHITE,fg=NAVY,font=("Segoe UI",14,"bold")).pack(anchor="w",pady=(4,1))
            tk.Label(card,text=desc,bg=WHITE,fg=MUTED,font=("Segoe UI",9)).pack(anchor="w")
        grid.columnconfigure(0,weight=1); grid.columnconfigure(1,weight=1)
        tk.Label(wrap, text="Note: this is an independent practice tool, not an official JAMB product.", bg=BG, fg=MUTED, font=("Segoe UI", 9)).pack(anchor="w", pady=(18,0))

    def mode_card(self,parent,title,meta,desc,mode,col):
        card=tk.Frame(parent,bg=WHITE,highlightbackground="#DDE4E0",highlightthickness=1,padx=20,pady=17)
        card.grid(row=0,column=col,sticky="nsew",padx=(0,10) if col==0 else (10,0))
        tk.Label(card,text=title,bg=WHITE,fg=NAVY,font=("Segoe UI",15,"bold")).pack(anchor="w")
        tk.Label(card,text=meta,bg=WHITE,fg=GREEN,font=("Segoe UI",10,"bold")).pack(anchor="w",pady=(5,8))
        tk.Label(card,text=desc,bg=WHITE,fg=MUTED,wraplength=350,justify="left",font=("Segoe UI",10)).pack(anchor="w")
        self.button(card,"Choose subjects →",lambda:self.choose_subjects(mode)).pack(anchor="w",pady=(15,0))
        parent.columnconfigure(0,weight=1); parent.columnconfigure(1,weight=1)

    def choose_subjects(self, mode):
        self.mode=mode
        self.clear(); self.header("SELECT A SUBJECT", "Choose one subject to begin your session")
        wrap=tk.Frame(self.root,bg=BG); wrap.pack(fill="both",expand=True,padx=42,pady=35)
        tk.Label(wrap,text="Which subject are you working on?",bg=BG,fg=NAVY,font=("Segoe UI",21,"bold")).pack(anchor="w")
        tk.Label(wrap,text=("Timed mode: 60 minutes" if mode=="exam" else "Practice mode: explanations available"),bg=BG,fg=MUTED,font=("Segoe UI",11)).pack(anchor="w",pady=(6,22))
        for name in SUBJECT_ORDER:
            row=tk.Frame(wrap,bg=WHITE,highlightbackground="#DDE4E0",highlightthickness=1,padx=18,pady=14); row.pack(fill="x",pady=6)
            left=tk.Frame(row,bg=WHITE); left.pack(side="left",fill="x",expand=True)
            tk.Label(left,text=name,bg=WHITE,fg=NAVY,font=("Segoe UI",14,"bold")).pack(anchor="w")
            tk.Label(left,text="60 questions available",bg=WHITE,fg=MUTED,font=("Segoe UI",9)).pack(anchor="w",pady=(3,0))
            self.button(row,"Start →",lambda n=name:self.start_session(n)).pack(side="right")
        self.button(wrap,"← Back to home",self.show_home,bg="#E2E8F0",fg=NAVY).pack(anchor="w",pady=(20,0))

    def start_session(self, subject):
        self.subject=subject; self.questions=SUBJECTS[subject][:60]; self.answers={}; self.flagged=set(); self.idx=0; self.remaining=3600
        self.show_question_screen()
        if self.mode=="exam": self.tick()

    def show_question_screen(self):
        self.clear()
        top=tk.Frame(self.root,bg=NAVY,padx=20,pady=12); top.pack(fill="x")
        tk.Label(top,text=self.subject.upper(),bg=NAVY,fg=WHITE,font=("Segoe UI",15,"bold")).pack(side="left")
        self.timer_label=tk.Label(top,text="PRACTICE MODE" if self.mode=="practice" else "60:00",bg=NAVY,fg="#6EE7C5",font=("Consolas",15,"bold")); self.timer_label.pack(side="right")
        body=tk.Frame(self.root,bg=BG); body.pack(fill="both",expand=True,padx=22,pady=18)
        main=tk.Frame(body,bg=BG); main.pack(side="left",fill="both",expand=True,padx=(0,18))
        side=tk.Frame(body,bg=WHITE,width=235,padx=14,pady=14,highlightbackground="#DDE4E0",highlightthickness=1); side.pack(side="right",fill="y"); side.pack_propagate(False)
        self.progress_label=tk.Label(main,text="QUESTION 1 OF 60",bg=BG,fg=GREEN,font=("Segoe UI",10,"bold")); self.progress_label.pack(anchor="w")
        self.q_text=tk.Label(main,text="",bg=WHITE,fg=NAVY,font=("Segoe UI",15),wraplength=680,justify="left",anchor="nw",padx=22,pady=22,relief="flat")
        self.q_text.pack(fill="x",pady=(12,15))
        self.options_frame=tk.Frame(main,bg=BG); self.options_frame.pack(fill="x")
        self.option_buttons=[]
        controls=tk.Frame(main,bg=BG); controls.pack(fill="x",pady=(20,0))
        self.button(controls,"← Previous",self.previous,bg="#E2E8F0",fg=NAVY).pack(side="left")
        self.button(controls,"Flag for review ⚑",self.toggle_flag,bg="#FFF0D8",fg="#8A5700").pack(side="left",padx=8)
        self.button(controls,"Next →",self.next_question).pack(side="right")
        tk.Label(side,text="QUESTION MAP",bg=WHITE,fg=NAVY,font=("Segoe UI",12,"bold")).pack(anchor="w")
        tk.Label(side,text="Tap a number to jump",bg=WHITE,fg=MUTED,font=("Segoe UI",9)).pack(anchor="w",pady=(3,12))
        self.palette=tk.Frame(side,bg=WHITE); self.palette.pack(fill="both",expand=True)
        self.palette_buttons=[]
        for i in range(len(self.questions)):
            b=tk.Button(self.palette,text=str(i+1),command=lambda j=i:self.jump(j),width=3,padx=0,pady=5,relief="flat",bd=0,cursor="hand2",font=("Segoe UI",9,"bold"))
            b.grid(row=i//5,column=i%5,padx=2,pady=3,sticky="ew"); self.palette_buttons.append(b)
        for c in range(5): self.palette.columnconfigure(c,weight=1)
        self.palette_legend=tk.Label(side,text="○ Unanswered   ● Answered\n⚑ Flagged for review",bg=WHITE,fg=MUTED,font=("Segoe UI",8),justify="left"); self.palette_legend.pack(anchor="w",pady=(10,12))
        self.button(side,"Submit session",self.submit,bg=GREEN).pack(fill="x")
        tk.Label(side,text="KEYBOARD SHORTCUTS\nA–E  Select answer\n← / →  Previous / Next\n1–9  Jump to question\nF  Flag for review\nHome / End  First / Last\nEsc  Return home\nCtrl+Enter  Submit",bg=WHITE,fg=MUTED,font=("Segoe UI",8),justify="left").pack(anchor="w",pady=(12,0))
        self.render_question()

    def render_question(self):
        q=self.questions[self.idx]
        self.progress_label.config(text=f"QUESTION {self.idx+1:02d} OF {len(self.questions)}")
        source=f"  •  {q.get('year','Practice')}" if q.get('year') else ""
        self.q_text.config(text=q['text']+source)
        for w in self.options_frame.winfo_children(): w.destroy()
        self.option_buttons=[]
        for key,val in sorted(q['options'].items()):
            selected=self.answers.get(self.idx)==key
            b=tk.Button(self.options_frame,text=f"{key}     {val}",anchor="w",justify="left",wraplength=650,
                        command=lambda k=key:self.select(k),bg=PALE if selected else WHITE,fg=NAVY,
                        activebackground=PALE,activeforeground=NAVY,relief="flat",bd=0,padx=18,pady=13,
                        font=("Segoe UI",11),highlightthickness=1,highlightbackground=GREEN if selected else "#DDE4E0",cursor="hand2")
            b.pack(fill="x",pady=4); self.option_buttons.append(b)
        if self.mode=="practice" and self.idx in self.answers:
            correct=q['answer']; chosen=self.answers[self.idx]
            result="Correct!" if chosen==correct else f"Not quite — correct answer: {correct}"
            tk.Label(self.options_frame,text=result+"\n"+q.get('explanation',''),bg=BG,fg=GREEN if chosen==correct else "#B45309",justify="left",wraplength=680,font=("Segoe UI",10)).pack(anchor="w",pady=8)
        self.refresh_palette()

    def select(self,key):
        self.answers[self.idx]=key; self.render_question()

    def refresh_palette(self):
        for i,b in enumerate(self.palette_buttons):
            if i in self.flagged: bg="#FDE7B4"
            elif i in self.answers: bg=PALE
            else: bg="#EEF1F4"
            if i==self.idx: bg=GREEN
            b.config(bg=bg,fg=WHITE if i==self.idx else NAVY)

    def previous(self):
        if self.idx>0: self.idx-=1; self.render_question()
    def next_question(self):
        if self.idx<len(self.questions)-1: self.idx+=1; self.render_question()
    def jump(self,i): self.idx=i; self.render_question()
    def toggle_flag(self):
        if self.idx in self.flagged: self.flagged.remove(self.idx)
        else: self.flagged.add(self.idx)
        self.refresh_palette()

    def tick(self):
        if not self.root.winfo_exists(): return
        mins,secs=divmod(max(0,self.remaining),60)
        self.timer_label.config(text=f"{mins:02d}:{secs:02d}",fg="#FFCF70" if self.remaining<300 else "#6EE7C5")
        if self.remaining<=0:
            messagebox.showinfo("Time is up","Your session will now be submitted.")
            self.submit(force=True); return
        self.remaining-=1
        self.timer_job=self.root.after(1000,self.tick)

    def submit(self,force=False):
        unanswered=len(self.questions)-len(self.answers)
        if not force and not messagebox.askyesno("Submit examination",f"You answered {len(self.answers)} of {len(self.questions)} questions.\nUnanswered: {unanswered}.\n\nSubmit now?"):
            return
        if self.timer_job:
            self.root.after_cancel(self.timer_job); self.timer_job=None
        correct=sum(1 for i,q in enumerate(self.questions) if self.answers.get(i)==q['answer'])
        self.show_results(correct)

    def show_results(self,correct):
        self.clear(); total=len(self.questions); pct=round(correct/total*100,1) if total else 0
        self.header("SESSION COMPLETE", f"{self.subject} · {'Timed examination' if self.mode=='exam' else 'Practice session'}")
        wrap=tk.Frame(self.root,bg=BG); wrap.pack(fill="both",expand=True,padx=40,pady=28)
        panel=tk.Frame(wrap,bg=WHITE,padx=28,pady=24,highlightbackground="#DDE4E0",highlightthickness=1); panel.pack(fill="x")
        tk.Label(panel,text="YOUR RESULT",bg=WHITE,fg=GREEN,font=("Segoe UI",10,"bold")).pack()
        tk.Label(panel,text=f"{correct} / {total}",bg=WHITE,fg=NAVY,font=("Segoe UI",36,"bold")).pack(pady=(6,0))
        tk.Label(panel,text=f"{pct}% score",bg=WHITE,fg=MUTED,font=("Segoe UI",13)).pack(pady=(0,15))
        barbg=tk.Frame(panel,bg="#E7ECE9",height=12); barbg.pack(fill="x",pady=(0,18)); barbg.pack_propagate(False)
        tk.Frame(barbg,bg=GREEN,width=int(600*correct/total),height=12).pack(side="left")
        tk.Label(panel,text=f"Answered: {len(self.answers)}     Unanswered: {total-len(self.answers)}     Flagged: {len(self.flagged)}",bg=WHITE,fg=TEXT,font=("Segoe UI",11)).pack()
        tk.Label(wrap,text="ANSWER REVIEW",bg=BG,fg=NAVY,font=("Segoe UI",13,"bold")).pack(anchor="w",pady=(22,8))
        review=tk.Text(wrap,height=12,wrap="word",font=("Segoe UI",10),bg=WHITE,fg=TEXT,relief="flat",padx=14,pady=12)
        review.pack(fill="both",expand=True)
        for i,q in enumerate(self.questions):
            user=self.answers.get(i,"—"); good=user==q['answer']; status="✓" if good else "✗"
            review.insert("end",f"{i+1}. {status}  Your answer: {user}  |  Correct: {q['answer']}\n{q['text']}\n")
            if self.mode=="practice" or not good: review.insert("end",f"Explanation: {q.get('explanation','')}\n")
            review.insert("end","\n")
        review.config(state="disabled")
        row=tk.Frame(wrap,bg=BG); row.pack(fill="x",pady=(14,0))
        self.button(row,"Choose another subject",lambda:self.choose_subjects(self.mode),bg="#E2E8F0",fg=NAVY).pack(side="left")
        self.button(row,"Back to home",self.show_home).pack(side="right")

def main():
    root=tk.Tk(); JambApp(root); root.mainloop()

if __name__ == '__main__':
    main()
